#include <iostream>

class Complex {
public:
    explicit Complex(double r = 0.0, double i = 0.0) : real(r), imaginary(i) {}

    Complex operator+(const Complex &rhs) const {
        return Complex(real + rhs.real, imaginary + rhs.imaginary);
    }

    Complex operator-(const Complex &rhs) const {
        return Complex(real - rhs.real, imaginary - rhs.imaginary);
    }

    void print() const {
        std::cout << '(' << real << ", " << imaginary << ')';
    }

private:
    double real{0.0};
    double imaginary{0.0};
};

int main() {
    Complex x;
    Complex y(4.3, 8.2);
    Complex z(3.3, 1.1);

    x = y + z;
    std::cout << "x = y + z: ";
    x.print();
    std::cout << " = ";
    y.print();
    std::cout << " + ";
    z.print();
    std::cout << '\n';

    x = y - z;
    std::cout << "x = y - z: ";
    x.print();
    std::cout << " = ";
    y.print();
    std::cout << " - ";
    z.print();
    std::cout << '\n';

    return 0;
}

#include <iostream>
#include <array>
#include <string>
#include <cctype>

class HugeIntDemo {
public:
    static const int digits = 10;

    HugeIntDemo(long value = 0) {
        integer.fill(0);
        for (int j = digits - 1; value != 0 && j >= 0; --j) {
            integer[j] = static_cast<short>(value % 10);
            value /= 10;
        }
    }

    HugeIntDemo(const std::string &number) {
        integer.fill(0);
        int len = static_cast<int>(number.size());
        for (int j = digits - len, k = 0; j < digits; ++j, ++k) {
            if (std::isdigit(static_cast<unsigned char>(number[k]))) {
                integer[j] = static_cast<short>(number[k] - '0');
            }
        }
    }

    void printDigits() const {
        for (int i = 0; i < digits; ++i) {
            std::cout << integer[i];
        }
        std::cout << '\n';
    }

private:
    std::array<short, digits> integer{};
};

int main() {
    HugeIntDemo h1(12345L);
    HugeIntDemo h2("9876");

    std::cout << "h1 internal digits: ";
    h1.printDigits();
    std::cout << "h2 internal digits: ";
    h2.printDigits();

    return 0;
}

#include <iostream>
#include <array>
#include <string>
#include <cctype>

class HugeInt {
    friend std::ostream &operator<<(std::ostream &out, const HugeInt &val);
public:
    static const int digits = 30;

    HugeInt(long val = 0) {
        integer.fill(0);
        for (int j = digits - 1; val != 0 && j >= 0; --j) {
            integer[j] = static_cast<short>(val % 10);
            val /= 10;
        }
    }

    HugeInt(const std::string &str) {
        integer.fill(0);
        int len = static_cast<int>(str.size());
        for (int j = digits - len, k = 0; j < digits; ++j, ++k) {
            if (std::isdigit(static_cast<unsigned char>(str[k]))) {
                integer[j] = static_cast<short>(str[k] - '0');
            }
        }
    }

    HugeInt operator+(const HugeInt &op2) const {
        HugeInt temp;
        int carry = 0;
        for (int i = digits - 1; i >= 0; --i) {
            temp.integer[i] = integer[i] + op2.integer[i] + carry;
            if (temp.integer[i] > 9) {
                temp.integer[i] %= 10;
                carry = 1;
            } else {
                carry = 0;
            }
        }
        return temp;
    }

    HugeInt operator+(int op2) const {
        return *this + HugeInt(op2);
    }

    HugeInt operator+(const std::string &op2) const {
        return *this + HugeInt(op2);
    }

private:
    std::array<short, digits> integer{};
};

std::ostream &operator<<(std::ostream &output, const HugeInt &num) {
    int i = 0;
    while (i < HugeInt::digits && num.integer[i] == 0) {
        ++i;
    }
    if (i == HugeInt::digits) {
        output << 0;
    } else {
        while (i < HugeInt::digits) {
            output << num.integer[i++];
        }
    }
    return output;
}

int main() {
    HugeInt n1(7654321);
    HugeInt n2(7891234);
    HugeInt n3("99999999999999999999999999999");
    HugeInt n4("1");
    HugeInt n5;

    std::cout << "n1 is " << n1 << "\nn2 is " << n2
              << "\nn3 is " << n3 << "\nn4 is " << n4
              << "\nn5 is " << n5 << "\n\n";

    n5 = n1 + n2;
    std::cout << n1 << " + " << n2 << " = " << n5 << "\n\n";

    std::cout << n3 << " + " << n4 << "\n= " << (n3 + n4) << "\n\n";

    n5 = n1 + 9;
    std::cout << n1 << " + 9 = " << n5 << "\n\n";

    n5 = n2 + std::string("10000");
    std::cout << n2 << " + 10000 = " << n5 << '\n';

    return 0;
}
